from typing import List

class Solution:
    def findMaximumXOR(self, nums: List[int]) -> int:
        best = 0
        mask = 0
        for bit in range(30, -1, -1):
            mask |= 1 << bit
            prefixes = {x & mask for x in nums}
            candidate = best | (1 << bit)
            for prefix in prefixes:
                if (prefix ^ candidate) in prefixes:
                    best = candidate
                    break
        return best

