from typing import List

class Solution:
    def findMaximumXOR(self, nums: List[int]) -> int:
        trie = {}
        for x in nums:
            node = trie
            for bit in range(30, -1, -1):
                b = (x >> bit) & 1
                node = node.setdefault(b, {})

        best = 0
        for x in nums:
            node = trie
            current = 0
            for bit in range(30, -1, -1):
                b = (x >> bit) & 1
                want = 1 - b
                if want in node:
                    current |= 1 << bit
                    node = node[want]
                else:
                    node = node[b]
            best = max(best, current)
        return best

